  "With an apple I will astonish Paris. — Paul Cézanne",
  "I have sworn to die painting. — Paul Cézanne",
  "Light is a thing that cannot be reproduced, but must be represented by something else - by color. — Paul Cézanne",
  "Everything we see falls apart, vanishes. Nature is always the same, but nothing in her that appears to us, lasts. — Paul Cézanne",
  "The painter must enclose himself within his work; he must respond not with words, but with paintings. — Paul Cézanne",
  "To my mind one does not put oneself in place of the past, one only adds a new link. — Paul Cézanne",
  "I am the master of my fate, I am the captain of my soul. — William Ernest Henley",
  "Life shrinks or expands in proportion to one's courage. — Anaïs Nin",
  "We don't see things as they are, we see them as we are. — Anaïs Nin",
