  "You live out the confusions until they become clear. — Anaïs Nin",
  "The truly great ones always reveal something of their lives, or they expose their philosophy. — Anaïs Nin",
  "There came a time when the risk to remain tight in the bud was more painful than the risk it took to blossom. — Anaïs Nin",
  "We do not grow absolutely, chronologically. We grow sometimes in one dimension, and not in another. — Anaïs Nin",
  "Age does not protect you from love. But love, to some extent, protects you from age. — Anaïs Nin",
  "I, with a deeper instinct, choose a man who compels my strength, who makes enormous demands on me, who does not doubt my courage or my toughness. — Anaïs Nin",
  "The only abnormality is the incapacity to love. — Anaïs Nin",
  "Music melts all the separate parts of our bodies together. — Anaïs Nin",
  "Shame is the lie someone told you about yourself. — Anaïs Nin",
  "The day came when the risk to remain tight in a bud was more painful than the risk it took to blossom. — Anaïs Nin",
  "I am only responsible for my own heart, you offered yours up for the smashing my darling. — Anaïs Nin",
  "There are very few human beings who receive the truth, complete and staggering, by instant illumination. — Anaïs Nin",
  "Life is a process of becoming. — Anaïs Nin",
