// function for showing quote //
function showrandomquote() {
  const i = Math.floor(Math.random() * randomquotes.length);
  document.getElementById("quote").textContent = randomquotes[i];
}

// listen for spacebar //
document.addEventListener("keydown", function (event) {
  if (event.code === "Space") {
    showrandomquote();
  }
});
